export const ModelSupportInvestigationModal__evidence_readiness_summary = ({ implementationReadyCount, partialCount, insufficientCount, notObservedCount }: { implementationReadyCount: number; partialCount: number; insufficientCount: number; notObservedCount: number }): string => `${implementationReadyCount} ${implementationReadyCount === 1 ? 'pronto para implementação' : 'prontos para implementação'}, ${partialCount} ${partialCount === 1 ? 'parcial' : 'parciais'}, ${insufficientCount} ${insufficientCount === 1 ? 'insuficiente' : 'insuficientes'}, ${notObservedCount} ${notObservedCount === 1 ? 'não observado' : 'não observados'}`;
